Test("Add returns the sum and leaves the operands alone", () =>
{
    var a = new Money(1250, "EUR");
    var sum = a.Add(new Money(250, "EUR"));
    Eq(sum == new Money(1500, "EUR"), true);
    Eq(a == new Money(1250, "EUR"), true);
});

Test("adding another currency throws", () =>
    Throws<InvalidOperationException>(() => new Money(100, "EUR").Add(new Money(100, "USD"))));

Test("Times multiplies the cents", () =>
    Eq(new Money(199, "USD").Times(3) == new Money(597, "USD"), true));

Test("ToString uses two decimals and the currency", () =>
{
    Eq(new Money(1234, "EUR").ToString(), "12.34 EUR");
    Eq(new Money(1500, "EUR").ToString(), "15.00 EUR");
});

Test("small and negative amounts format correctly (boundary)", () =>
{
    Eq(new Money(-5, "EUR").ToString(), "-0.05 EUR");
    Eq(new Money(0, "GBP").ToString(), "0.00 GBP");
});

Test("equality is value-based", () =>
{
    Eq(new Money(1, "EUR") == new Money(1, "EUR"), true);
    Eq(new Money(1, "EUR") == new Money(1, "USD"), false);
});

